"""The CORDIC configurations which are generated and verified by the CI.

The list below is the single source of truth for

* the RTL which is generated by ``cordic.py``,
* the cocotb test modules (``test_cordic_<arch>_<mode>.py``) and
* the verilator builds which are performed by ``conftest.py``.

The table covers every combination of the four supported architectures and the
two supported CORDIC modes.  The datapath width and the number of iterations
are varied as well to exercise the configurability of the module.
"""

from __future__ import annotations

ARCHES = ("comb", "pipelined", "loop", "loop_pipelined")
MODES = ("rotation", "vectoring")

_ARCH_TAG = {
    "comb": "Comb",
    "pipelined": "Pipelined",
    "loop": "Loop",
    "loop_pipelined": "LoopPipelined",
}

_MODE_TAG = {
    "rotation": "Rot",
    "vectoring": "Vec",
}


def cordic_name(arch: str, mode: str, width: int, iterations: int) -> str:
    """The name of the generated SystemVerilog module."""
    return f"Cordic{_ARCH_TAG[arch]}{_MODE_TAG[mode]}W{width}I{iterations}"


def test_module_name(arch: str, mode: str) -> str:
    """The name of the pytest/cocotb module which verifies a configuration."""
    return f"pycde_example.test_cordic_{arch}_{mode}"


CORDIC_CONFIGS: list[dict[str, object]] = [
    {"arch": "comb", "mode": "rotation", "width": 16, "iterations": 12},
    {"arch": "comb", "mode": "vectoring", "width": 16, "iterations": 12},
    {"arch": "pipelined", "mode": "rotation", "width": 24, "iterations": 12},
    {"arch": "pipelined", "mode": "vectoring", "width": 24, "iterations": 12},
    {"arch": "loop", "mode": "rotation", "width": 32, "iterations": 16},
    {"arch": "loop", "mode": "vectoring", "width": 32, "iterations": 16},
    {"arch": "loop_pipelined", "mode": "rotation", "width": 16, "iterations": 12},
    {"arch": "loop_pipelined", "mode": "vectoring", "width": 16, "iterations": 12},
]

for _cfg in CORDIC_CONFIGS:
    _cfg["name"] = cordic_name(_cfg["arch"], _cfg["mode"], _cfg["width"], _cfg["iterations"])
    _cfg["test_module"] = test_module_name(_cfg["arch"], _cfg["mode"])
